mapper.select:
SELECT FROM `reconcile_log` r WHERE r.`task_type` IN ('stock', 'reconcile-a', 'reconcile-b', 'route', 'orphan-route') AND (r.`diff` <> 0 OR r.`fix_action` = 'bucket-mismatch') AND (r.`task_type` IN ('route', 'orphan-route') OR EXISTS ( SELECT 1 FROM `slot` s WHERE s.`slot_id` = r.`slot_id` AND s.`slot_date` >= #{currentDate} )) AND NOT EXISTS ( SELECT 1 FROM `reconcile_log` newer WHERE newer.`task_type` = r.`task_type` AND newer.`slot_id` = r.`slot_id` AND (newer.`create_at` > r.`create_at` OR (newer.`create_at` = r.`create_at` AND newer.`id` > r.`id`)) )
AND r.`task_type` = #{taskType}
ORDER BY r.`slot_id`, r.`create_at` DESC LIMIT #{limit}
